// ==========================================
// 2. 狀態管理
// ==========================================
let activeVocabulary = [];
let currentWord = null;
let currentQuiz = null;
let quizMode = 'choice'; // 'choice' or 'dialogue'
let currentChoices = [];

function updateActiveVocabulary() {
  activeVocabulary = [];
  const checkboxes = document.querySelectorAll('.unit-checkbox:checked');
  checkboxes.forEach(cb => {
    const unitKey = cb.value;
    if (courseData[unitKey]) activeVocabulary = activeVocabulary.concat(courseData[unitKey]);
  });
  if (activeVocabulary.length === 0) {
    alert("請至少選擇一個單元進行學習喔！");
    return false;
  }
  return true;
}

function loadNextWord() {
  if (!updateActiveVocabulary()) return;
  const randomIndex = Math.floor(Math.random() * activeVocabulary.length);
  currentWord = activeVocabulary[randomIndex];
  currentQuiz = currentWord.quiz;
  renderWordCard(currentWord);
  renderQuiz(currentQuiz);
  const chatLog = document.getElementById("chat-log");
  if (chatLog) chatLog.innerHTML = "";
  const rs = document.getElementById("record-status");
  if (rs) rs.innerText = "等待指令...";
  const fb = document.getElementById("quiz-feedback");
  if (fb) fb.innerHTML = "";
}

function renderWordCard(data) {
  const badge = document.getElementById("word-unit-badge");
  if (badge) badge.innerText = data.unit;
  const title = document.getElementById("word-title");
  if (title) title.innerText = data.word;
  const trans = document.getElementById("word-translation");
  if (trans) trans.innerText = `${data.partOfSpeech}. ${data.translation}`;
  const ex = document.getElementById("word-example");
  if (ex) ex.innerText = data.example;
  const exCn = document.getElementById("word-example-cn");
  if (exCn) exCn.innerText = data.exampleCn;
  const grammarBox = document.getElementById("grammar-box");
  if (data.grammar && grammarBox) {
    grammarBox.style.display = "block";
    document.getElementById("grammar-title").innerText = data.grammar.title;
    document.getElementById("grammar-content").innerText = data.grammar.content;
    document.getElementById("grammar-note").innerText = data.grammar.note;
  } else if (grammarBox) {
    grammarBox.style.display = "none";
  }
}

function renderQuiz(quiz) {
  if (!quiz) return;
  document.getElementById("quiz-question-en").innerText = quiz.question;
  document.getElementById("quiz-question-cn").innerText = quiz.questionCn || "";
  document.getElementById("quiz-hint").innerText = "💡 提示：" + quiz.hintCn;
  const exp = document.getElementById("quiz-expected");
  if (exp) exp.innerText = "";
  const fb = document.getElementById("quiz-feedback");
  if (fb) fb.innerHTML = "";
  
  if (quizMode === 'choice') {
    renderChoiceMode(quiz);
  } else {
    renderDialogueMode();
  }
  
  // iPhone 不自動播放，必須由使用者手勢觸發，否則會被系統阻擋
  if (isIOSDevice()) {
    addSystemLog('📱 iPhone 模式：不自動播放，請點擊 🔊 按鈕', false);
    // 顯示提示
    const hint = document.getElementById("quiz-hint");
    if (hint && !hint.innerText.includes('iPhone')) {
      hint.innerText += ' | 📱 iPhone 請點 🔊 聽問句';
    }
  } else {
    setTimeout(() => speakText(quiz.question), 300);
  }
}

// ==========================================
// 選擇題模式 - 保證不超出自訂題庫
// ==========================================
function generateChoices(currentQuiz) {
  const correct = currentQuiz.expectedAnswer;
  // 只從已選範圍的 activeVocabulary 取干擾選項，保證不出題庫
  let pool = activeVocabulary.filter(v => v.quiz && v.quiz.expectedAnswer !== correct);
  
  // 優先：同單元 + 同文法類型的答案當干擾項，更有鑑別度
  let sameUnit = pool.filter(v => v.unit === currentWord.unit);
  let sameGrammar = sameUnit.filter(v => v.grammar && currentWord.grammar && v.grammar.title === currentWord.grammar.title);
  
  let candidates = [];
  if (sameGrammar.length >= 3) candidates = sameGrammar;
  else if (sameUnit.length >= 3) candidates = sameUnit;
  else candidates = pool;

  // 洗牌後取3個
  candidates = shuffleArray(candidates).slice(0, 3);
  let choices = candidates.map(c => c.quiz.expectedAnswer);
  
  // 補不足的（例如題庫太小時）用其他單元的答案
  while (choices.length < 3 && pool.length > choices.length) {
    let extra = pool.filter(p => !choices.includes(p.quiz.expectedAnswer));
    if (extra.length === 0) break;
    choices.push(extra[0].quiz.expectedAnswer);
  }
  
  // 加入正確答案並洗牌
  choices.push(correct);
  choices = shuffleArray(choices);
  
  // 去重（避免重複答案）
  choices = [...new Set(choices)];
  while (choices.length < 4) {
    choices.push(correct); // 保底，避免不足4個
    choices = [...new Set(choices)];
    if (choices.length >= 4) break;
  }
  
  return choices.slice(0,4);
}

function shuffleArray(arr) {
  let a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

